      "met": true
    },
    {
      "criterion": "When inserted mods are present, the confirmation dialog message includes the count and risk detail for insertions.",
      "met": true
    },
    {
      "criterion": "When both removed and inserted mods are present, both detail lines appear in the confirmation message.",
      "met": true
    },
    {
      "criterion": "The overall message uses `ConfirmUpdateMessage_RiskyChanges` as the template with detail lines embedded via `{0}` format placeholder.",
      "met": true
    },
    {
      "criterion": "When only safe changes are present (added/replaced only), no confirmation dialog is shown and the operation proceeds directly — this preserves the current behavior.",
      "met": true
    },
    {
      "criterion": "The confirmation dialog title (`ConfirmUpdateTitle`) and icon (`ConfirmationIcon.Warning`) remain unchanged.",
      "met": true
    }
